def split_csv(line):
    if not line:
        return ['']

    fields = []
    i = 0

    while i <= len(line):
        if i == len(line):
            fields.append('')
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = ''
            while i < len(line):
                if line[i] == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        if i < len(line):
                            if line[i] == ',':
                                i += 1
                            else:
                                return None
                        fields.append(field)
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field
            field = ''
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    return None
                field += line[i]
                i += 1

            fields.append(field)
            if i < len(line):
                i += 1

    return fields

